"use client";

import * as React from "react";

import { UiThinking } from "@/components/lumesec/ui-thinking";

export function Example() {
  const [done, setDone] = React.useState(false);
  React.useEffect(() => {
    const timer = window.setTimeout(() => setDone(true), 4000);
    return () => window.clearTimeout(timer);
  }, []);
  return (
    <UiThinking done={done} onDone={(seconds) => console.log(`thought for ${seconds}s`)}>
      The reasoning, shown once thinking is done.
    </UiThinking>
  );
}

