import { UiSendButton, type UiSendButtonHandle } from "@/components/lumesec/ui-send-button";

export function Example() {
  const button = React.useRef<UiSendButtonHandle>(null);
  const timer = React.useRef(0);
  return (
    <UiSendButton
      ref={button}
      onSend={() => {
        // stand-in for a streamed reply
        timer.current = window.setTimeout(() => button.current?.complete(), 2000);
      }}
      onStop={() => window.clearTimeout(timer.current)}
    />
  );
}

